package com.codereview.app.auth;

@RestController
@RequestMapping("/auth")
public class AuthController {

    private final JwtValidator jwtValidator;

    public AuthController(JwtValidator jwtValidator) {
        this.jwtValidator = jwtValidator;
    }

    @PostMapping("/login")
    public ResponseEntity<LoginResponse> login(@RequestBody LoginRequest request) {
        if (!InMemoryUsers.isValid(request.username(), request.password())) {
            return ResponseEntity.status(401).build();
        }
        return ResponseEntity.ok(new LoginResponse(jwtValidator.generateToken(request.username())));
    }
}

package com.codereview.app.auth;

final class InMemoryUsers {

    private static final Map<String, String> CREDENTIALS = Map.of("admin", "admin123");

    private InMemoryUsers() {
    }

    static boolean isValid(String username, String password) {
        return CREDENTIALS.getOrDefault(username, "").equals(password);
    }
}

package com.codereview.app.auth;

public record LoginResponse(String token) {
}
